+const TWO_PART_PUBLIC_SUFFIXES = new Set(["co.uk", "org.uk", "ac.uk", "com.au", "com.br"]);
+const PUBLIC_SUFFIX_LIKE_SECOND_LEVEL_LABELS = new Set([
+  "ac",
+  "co",
+  "com",
+  "edu",
+  "go",
+  "gov",
+  "net",
+  "ne",
+  "or",
+  "org",
+]);
+
+export const registrableApexHost = (value: string): string => {
+  const host = normalizedHost(value);
+  const labels = host.split(".").filter(Boolean);
+  if (labels.length <= 2) return host;
+  const lastTwo = labels.slice(-2).join(".");
+  if (TWO_PART_PUBLIC_SUFFIXES.has(lastTwo)) return labels.slice(-3).join(".");
+  const secondLevel = labels.at(-2);
+  const topLevel = labels.at(-1);
+  if (
+    secondLevel &&
+    topLevel?.length === 2 &&
+    PUBLIC_SUFFIX_LIKE_SECOND_LEVEL_LABELS.has(secondLevel)
+  ) {
+    return host;
+  }
+  const suffixLabels = 2;
+  return labels.slice(-suffixLabels).join(".");
+};
+
+export const hostWithinDomainGrantApex = (
+  host: string,
+  allowedHosts: readonly string[],
+): boolean => {
+  const requested = normalizedHost(host);
+  const requestedIpFamily = isIP(requested);
+  return allowedHosts.some((allowedHost) => {
+    const allowed = normalizedHost(allowedHost);
+    const allowedIpFamily = isIP(allowed);
+    if (requestedIpFamily !== 0 || allowedIpFamily !== 0) return requested === allowed;
+    return registrableApexHost(allowed) === registrableApexHost(requested);
+  });
+};
