+    readonly error_class:
+      | "provider_error"
+      | "rate_limited"
+      | "timeout"
+      | "parse_error"
+      | "schema_validation_error";
+    readonly message: string;
+    readonly safeDetails?: Record<string, unknown>;
+  }) {
+    super({
+      kind: "validation_error",
+      message: options.message,
+      safeDetails: {
+        provider_used: "openrouter",
+        error_class: options.error_class,
+        ...(scrubLlmUnsafeRecord(options.safeDetails) ?? {}),
+      },
+    });
+    this.name = "AiProviderInvocationError";
+    this.error_class = options.error_class;
+    this.provider_used = "openrouter";
+  }
+}
+
+export interface InMemoryCallModelAuditSink extends CallModelAuditSink {
+  readonly llm_calls: CallModelLlmCallRow[];
+  readonly observability_events: CallModelObservabilityEvent[];
+}
