+  readonly cache_key_version: "llm-cache-key.v1";
+  readonly input_fingerprint: string;
+  readonly prompt_hash: string;
+  readonly source_artifact_ids: readonly PrefixedIdString<"art">[];
+  readonly image_inputs_fingerprint: string | null;
+  readonly image_input_manifest: ReturnType<typeof imageInputAuditManifest>;
+}
+
+export interface CallModelOptions<TOutput> {
+  readonly provider?: FakeProvider | LlmProvider;
+  readonly audit: CallModelAuditSink;
+  readonly outputSchema: z.ZodType<TOutput>;
+  readonly structuredOutputSchema?: z.ZodType<unknown> | undefined;
+  readonly prompt: string;
+  readonly image_inputs?: readonly LlmImageInput[] | undefined;
+  readonly scenario?: string;
+  readonly profile?: ModelProfile;
+  readonly task_type?: string;
+  readonly run_id?: PrefixedIdString<"run">;
+  readonly trace_id?: PrefixedIdString<"trace">;
+  readonly correlation_id?: string;
+  readonly prompt_version?: string;
+  readonly source_artifact_ids?: readonly PrefixedIdString<"art">[];
+  readonly attempt_group_id?: string;
+  readonly max_estimated_cost_usd?: number;
+  readonly estimated_cost_usd?: number | undefined;
+  readonly repair_scenario?: string;
+  readonly max_repair_attempts?: number;
+  readonly fallback_scenario?: string;
+  readonly expected_output_schema_version?: string;
+  readonly semanticValidator?: (output: TOutput) => string | null;
+  readonly cache?: CallModelCache;
+  readonly cache_key?: string;
+  readonly cache_enabled?: boolean;
+  readonly lockStore?: LlmCacheLockStore;
+  readonly lock_ttl_ms?: number;
+  readonly lock_stale_ms?: number;
+  readonly lock_wait_timeout_ms?: number;
+  readonly budgetStore?: AiBudgetStore;
+  readonly budgetEnv?: NodeJS.ProcessEnv;
+}
+
+export interface CallModelResult<TOutput> {
+  readonly ok: true;
+  readonly output: TOutput;
+  readonly attempt_group_id: string;
+  readonly attempts: readonly CallModelLlmCallRow[];
+  readonly cache_hit: boolean;
+  readonly cache_key: string | null;
+}
