+export const parseMicromotorSelection = (values: readonly string[]): readonly string[] => {
+  const ordered: string[] = [];
+  const seen = new Set<string>();
+  for (const raw of values) {
+    for (const part of raw.split(",")) {
+      const slug = part.trim();
+      if (!isPublicSlug(slug) || seen.has(slug)) continue;
+      seen.add(slug);
+      ordered.push(slug);
+    }
+  }
+  return ordered;
+};
+
+export const selectionQuery = (slugs: readonly string[]): string => {
+  const params = new URLSearchParams();
+  for (const slug of slugs) params.append("ids", slug);
+  const query = params.toString();
+  return query.length > 0 ? `?${query}` : "";
+};
+
+export const compareHref = (slugs: readonly string[]): string => `/compare${selectionQuery(slugs)}`;
+
+export const listingHref = (slugs: readonly string[], replace?: string | null): string => {
+  const params = new URLSearchParams(selectionQuery(slugs).replace(/^\?/, ""));
+  if (replace && isPublicSlug(replace)) params.set("replace", replace);
+  const query = params.toString();
+  return `/micromotors${query.length > 0 ? `?${query}` : ""}`;
+};
+
+export const productHref = (slug: string, slugs: readonly string[]): string =>
+  `/products/${slug}${selectionQuery(slugs)}`;
+
+export type SelectionChange =
+  | { readonly kind: "selected"; readonly ids: readonly string[] }
+  | {
+      readonly kind: "replace_required";
+      readonly ids: readonly string[];
+      readonly incoming: string;
+    };
