+  if (replace && isPublicSlug(replace) && current.includes(replace)) {
+    return {
+      kind: "selected",
+      ids: current.map((id) => (id === replace ? slug : id)),
+    };
+  }
+  return { kind: "replace_required", ids: current, incoming: slug };
+};
+
+export const removeMicromotor = (current: readonly string[], slug: string): readonly string[] =>
+  current.filter((id) => id !== slug);

